/** Find the Tally PDFs already in Drive (uploaded through "Upload a Tally invoice" or saved by Tally) and link them to the orders that have none (owner, 9 Nov 2026). */
function corpPdfScan_(d, user) {
  corpUser_(user);
  const have = corpPdfMap_(), key = inv => { const m = String(inv).match(/NF\s*[\/_\- ]\s*(?:20)?26\s*[-_]\s*27\s*[\/_\- ]\s*0*(\d+)/i); return m ? 'NF' + Number(m[1]) : ''; };
  const orders = xrows_(PS_TAB, PS_H).filter(r => /^CORP-/.test(s_(r[0])) && !have[s_(r[0])] && !/PDF https:\/\/drive\.google\.com\/file\/d\//.test(s_(r[18])));
  if (!orders.length) return { found: [], missing: [] };
  const files = {}, it = DriveApp.searchFiles("title contains 'NF' and mimeType = 'application/pdf' and trashed = false");
  while (it.hasNext()) { const f = it.next(), k = key(f.getName()); if (k && (!files[k] || f.getLastUpdated() > files[k].getLastUpdated())) files[k] = f; }
  const sh = xtab_(CPDF_TAB, CPDF_H), found = [], missing = [];
  orders.forEach(r => { const k = key(s_(r[1])), f = k && files[k];
    if (f) { sh.appendRow([s_(r[0]), s_(r[1]), f.getId(), f.getName(), 'Linked automatically', new Date()]); found.push(s_(r[1]) + ' ← ' + f.getName()); } else missing.push(s_(r[1])); });
  return { found: found, missing: missing };
}
function corpAutoScan_(user) {
  const c = CacheService.getScriptCache(); if (c.get('corpPdfScan')) return;
  try { corpPdfScan_({}, user); } catch (e) { } c.put('corpPdfScan', '1', 600);
}
